BEGIN;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS is_proposal boolean NOT NULL DEFAULT false;
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS category text NOT NULL DEFAULT 'Catálogo';
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS characteristics text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS color_hex text;
ALTER TABLE public.product_variants ADD COLUMN IF NOT EXISTS image_url text;
NOTIFY pgrst, 'reload schema';
COMMIT;
SELECT (SELECT count(*) FROM public.products WHERE is_proposal) AS proposals,(SELECT count(*) FROM public.product_variants v JOIN public.products p ON p.id=v.product_id WHERE p.is_proposal) AS color_variants;
